  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is PartnerNotificationPreferences &&
          other.newRequestAlwaysOn == newRequestAlwaysOn &&
          other.messages == messages &&
          other.reviews == reviews &&
          other.vouchers == vouchers &&
          other.visits == visits;

  @override
  int get hashCode => Object.hashAll([newRequestAlwaysOn, messages, reviews, vouchers, visits]);

  @override
  String toString() => 'PartnerNotificationPreferences(${toJson()})';
}
